description:
Implement the Verilog module based on the following description.
Build a 12-bit counter with enable and synchronous reset. The counter should reset to a specific value.
// (1) enable: Enables the counter. Active high.
// (2) reset: Synchronous reset of the counter. Active high.
// (3) clk: Clock signal.
// (4) q: 12-bit output of the counter.
// (5) reset_value: 12-bit reset value for the counter.
module top_module(
	input clk,
	input enable,
	input reset,
	input [11:0] reset_value,
	output reg [11:0] q);

code:
module top_module(
	input clk,
	input enable,
	input reset,
	input [11:0] reset_value,
	output reg [11:0] q);always @(posedge clk) begin
	if (reset)
		q <= reset_value;
	else if (enable)
		q <= q + 1;
end
endmodule

