module top_module(
    input clk,
    input [17:0] data,
    input ena,
    input aclr,
    output reg [17:0] dataout
);// Internal signals
    reg [17:0] data_reg;
    reg [17:0] dataout_tmp;
    reg d_viol;
    reg ena_viol;

    // Timing constraints
    parameter t_setup = 1;
    parameter t_hold = 1;

    // Setup and hold checks
    always @(posedge clk or negedge aclr) begin
        if (!aclr) begin
            d_viol <= 0;
            ena_viol <= 0;
        end else begin
            d_viol <= !(ena && clk) || (data !== data_reg); // A simple violation check
            ena_viol <= !aclr && !ena; // Example condition for enable violation
        end
    end

    // Register logic
    always @(posedge clk or negedge aclr) begin
        if (!aclr) begin
            data_reg <= 0;
            dataout_tmp <= 0;
        end else if (ena && !d_viol) begin
            data_reg <= data;
        end
    end

    // Output logic
    always @(posedge clk or negedge aclr) begin
        if (!aclr) begin
            dataout <= 0;
        end else if (ena && !ena_viol) begin
            dataout_tmp <= data_reg;
        end
    end

    // Assign output
    always @* begin
        dataout = dataout_tmp;
    end

endmodule

