module fsm (
	input clk,
	input reset_n,
	input p,
	input q,
	output reg x);

	parameter J=0, K=1, S1=2, S2=3, S3=4, S4=5;
	reg [2:0] state, next;

	always @(posedge clk) begin
		if (!reset_n) state <= J;
		else state <= next;
	end

	always_comb begin
		case (state)
			J: next = p ? K : J;
			K: next = q ? S1 : S2;
			S1: next = q ? S2 : S3;
			S2: next = q ? S3 : S4;
			S3: next = q ? S4 : J;
			S4: next = p ? K : J;
			default: next = 'x;
		endcase
	end

	assign x = (state == S1);

endmodule

