reg [3:0] rotabit = 0; 						
reg [3:0] contador = 0;
parameter [6:0] cero = 	~7'h3F; 			
parameter [6:0] uno 	= 	~7'h06; 
parameter [6:0] dos 	= 	~7'h5B; 
parameter [6:0] tres = 	~7'h4F;

