begin
cuenta_para_1hz = cuenta_para_1hz + 1;
if(cuenta_para_1hz == 25_000_000)
begin
clock_1hz = ~clock_1hz; 					
cuenta_para_1hz = 0; 						
end
end


always @(posedge clock_50mhz) 			
begin
cuenta_para_2khz = cuenta_para_2khz + 1;
