begin
clock_2khz = ~clock_2khz; 					
cuenta_para_2khz = 0; 						
end
end


always @(posedge clock_2khz)
begin
case(rotabit)
0: rotabit <= 1;
1: rotabit <= 2;
2: rotabit <= 3;
3: rotabit <= 0;
endcase
end


always @(rotabit)
begin
