output [6:0]c;
input [6:0]r;  
output reg [6:0]e;   
output reg [3:0]d;   
output reg [2:0]s; 
always@(posedge clk) 
	begin
		s[2]=r[6]^r[2]^r[3]^r[4]; 
		s[1]=r[6]^r[1]^r[3]^r[5]; 
		s[0]=r[0]^r[4]^r[5]^r[6]; 
end
always@(posedge clk)
	begin
