			0 : e= 7'b0000000;        
			1 : e= 7'b0000001;          
			2 : e= 7'b0000010;
			3 : e= 7'b0100000;
			4 : e= 7'b0000100;      
			5 : e= 7'b0010000;
			6 : e= 7'b0001000;
			7 : e= 7'b1000000;
			default: e=7'bzzzzzzz; 
endcase
