xor a3(c[2],e[2],r[2]);
xor a4(c[3],e[3],r[3]);
xor a5(c[4],e[4],r[4]);
xor a6(c[5],e[5],r[5]);
xor a7(c[6],e[6],r[6]);
always@(c)
begin
	d[0]=c[3];
