module time_based_lock (
	input clk,
	input resetn,
	input correct_code,
	output locked);

	parameter LOCKED=0, UNLOCKED=1, TIMEOUT=2;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= LOCKED;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == UNLOCKED) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			LOCKED: next_state = correct_code ? UNLOCKED : LOCKED;
			UNLOCKED: next_state = (counter == 4'd9) ? TIMEOUT : UNLOCKED;
			TIMEOUT: next_state = LOCKED;
			default: next_state = LOCKED;
		endcase
	end

	assign locked = (state == LOCKED);
endmodule

