module top_module(
    input wire clk_icap,   // WARNING: this clock must not be greater than 20MHz (50ns period)
    input wire mrst_n,
    output reg reboot_ff
    );reg [4:0] q = 5'b00000;
    always @(posedge clk_icap) begin
      q[0] <= ~mrst_n;
      q[1] <= q[0];
      q[2] <= q[1];
      q[3] <= q[2];
      q[4] <= q[3];
      reboot_ff <= (q[4] && (!q[3]) && (!q[2]) && (!q[1]) );
    end

endmodule

