    input [3:0] A,
    input clk,  // Added clk input
    output reg [15:0] Y
);reg [15:0] Y1, Y2, Y3, Y4;

always @ (posedge clk) begin
    Y1 <= 16'b1111111111111111; // Initialize Y1 to all ones
    Y1[A] <= 1'b0; // Set the Y1 output corresponding to input A to 0
end

assign Y = Y4;

always @ (posedge clk) begin
    Y2 <= Y1;
end

always @ (posedge clk) begin
    Y3 <= Y2;
end

always @ (posedge clk) begin
    Y4 <= Y3;
end

