module top_module(
  input signed [2:0] x,
  input signed [2:0] y,
  input clk,
  output reg signed [5:0] z, // Change to reg since we are assigning in an always block
  output reg ready           // Change to reg to allow assignment in always block
);reg signed [5:0] a;
  reg signed [2:0] m;
  reg signed [2:0] q;
  reg [1:0] state;

  always @(posedge clk) begin
    case(state)
      2'b00: begin
        q <= {1'b0, y};
        m <= -x;
        state <= 2'b01;
        ready <= 0; // Initialize ready as 0
      end
      2'b01: begin
        if(q[0] == 1) begin
          a <= a + m;
        end
        q <= q >> 1;
        m <= m << 1;
        state <= 2'b10;
      end
      2'b10: begin
        q <= {a[5], q[2:1]};
        if(q == 3'b000) begin // Check q instead of state
          ready <= 1;
          state <= 2'b11;
        end else begin
          state <= 2'b01;
        end
      end
      2'b11: begin
        ready <= 0;
        state <= 2'b00;
      end
    endcase
    z <= a; // Assign a to z in each clock cycle
  end

endmodule

