module top_module(
    input [15:0] in,
    input clk,  // Added clk input
    output reg [4:0] num_zeros
);reg [3:0] stage1_out;
reg [2:0] stage2_out;
reg [1:0] stage3_out;
reg stage4_out;

always @(posedge clk) begin
    stage1_out <= {stage1_out[2:0], in[0]};
end

always @(posedge clk) begin
    stage2_out <= {stage2_out[1:0], stage1_out[3]};
end

always @(posedge clk) begin
    stage3_out <= {stage3_out[0], stage2_out[2]};
end

always @(posedge clk) begin
    stage4_out <= stage3_out[1] & stage3_out[0];
end

always @(posedge clk) begin
    if (stage4_out == 1'b0) begin
        num_zeros <= 0;
    end else if (stage3_out[1] == 1'b0) begin
        num_zeros <= 1;
    end else if (stage2_out[2] == 1'b0) begin
        num_zeros <= 2;
    end else if (stage1_out[3] == 1'b0) begin
        num_zeros <= 3;
    end else begin
        num_zeros <= 4;
    end
end

endmodule

