description:
Design a reset synchronizer that transfers an asynchronous active-low reset signal (rst_n) into a synchronized reset output (rst) suitable for use in a synchronous clock domain. The module ensures that the reset signal is properly synchronized to the clock signal (clk) by using a two-stage flip-flop technique. When rst_n is asserted low, the synchronized reset will be held high until it is safely reset in the clock domain, preventing glitches in the circuit operation.
module top_module(
  input rst_n,
  input clk,
  output reg rst
);

code:
module top_module(
  input rst_n,
  input clk,
  output reg rst
);// Define parameters
parameter WIDTH = 1; // Width of the signals

// Define flip-flops
reg [1:0] rst_sync;

// Synchronize reset signal to clock domain
always @(posedge clk or negedge rst_n) begin
  if (~rst_n) begin
    rst_sync <= 2'b11;
  end else begin
    rst_sync[0] <= rst_sync[1];
    rst_sync[1] <= rst_n;
  end
end

// Output synchronized reset signal
assign rst = rst_sync[0];

endmodule

