module top_module (
        input clk,
        input areset,
        input temp_low,
        input temp_high,
        output reg heat_on);parameter Off = 1'b0, On = 1'b1;
	reg state;
	always @(posedge clk, posedge areset) begin
		if (areset)
			state <= Off;
		else begin
			case (state)
				Off: state <= temp_low ? On : Off;
				On: state <= temp_high ? Off : On;
			endcase
		end
	end

	assign heat_on = (state == On);

endmodule

