module top_module(
    input D,
    input SCD,
    input SCE,
    input GATE,
    input VPWR,
    input VGND,
    input VPB,
    input VNB,
    output Q
);reg Q_reg;
    wire SCD_or_D;
    wire mux_out;
    reg reset; // Changed from wire to reg
    reg power_good;

    assign SCD_or_D = (GATE == 1'b1) ? SCD : D;
    assign mux_out = (SCE == 1'b1) ? SCD_or_D : D;

    always @ (posedge VPWR or negedge VGND) begin
        if (VPWR == 1'b1 && VGND == 1'b0) begin
            reset <= 1'b1; // Use 1'b1 for clarity
            Q_reg <= 1'b0;
            power_good <= 1'b1;
        end
        else begin
            reset <= 1'b0;
            power_good <= 1'b0;
        end
    end

    always @ (negedge VPWR or posedge VGND) begin
        if (VGND == 1'b0 && VPWR == 1'b1) begin
            power_good <= 1'b1;
        end
        else begin
            power_good <= 1'b0;
        end
    end

    always @ (negedge VPWR or posedge VGND) begin
        if (VGND == 1'b0 && VPWR == 1'b1) begin
            Q_reg <= 1'b0;
        end
    end

    always @ (posedge SCE or posedge GATE or posedge D or posedge SCD_or_D or posedge reset) begin
        if (reset == 1'b1) begin
            Q_reg <= 1'b0;
        end
        else begin
            Q_reg <= mux_out;
        end
    end

    assign Q = Q_reg;

endmodule

