module top_module(
  input trigger,
  input clock,
  input reset,
  output reg pulse // Change output to reg
);parameter pulse_duration = 10; // pulse duration in clock cycles
parameter pulse_frequency = 1; // pulse frequency in Hz
parameter pulse_duty_cycle = 50; // pulse duty cycle in percent

reg [31:0] pulse_counter;
reg [31:0] pulse_duration_counter;
reg astable_mode;
reg monostable_mode;

always @(posedge clock) begin
  if (reset) begin
    pulse_counter <= 0;
    pulse_duration_counter <= 0;
    astable_mode <= 0;
    monostable_mode <= 0;
    pulse <= 0;
  end else begin
    if (trigger) begin
      pulse_duration_counter <= pulse_duration;
      monostable_mode <= 1;
    end
    if (pulse_duration_counter > 0) begin
      pulse <= 1;
      pulse_duration_counter <= pulse_duration_counter - 1;
    end else begin
      pulse <= 0;
      monostable_mode <= 0;
    end
    if (astable_mode) begin
      if (pulse_counter < (pulse_frequency * 2)) begin
        if (pulse_counter < (pulse_frequency * pulse_duty_cycle / 100)) begin
          pulse <= 1;
        end else begin
          pulse <= 0;
        end
        pulse_counter <= pulse_counter + 1;
      end else begin
        pulse_counter <= 0;
      end
    end
  end
end

always @(posedge clock) begin
  if (reset) begin
    pulse_counter <= 0;
    pulse_duration_counter <= 0;
    astable_mode <= 0;
    monostable_mode <= 0;
    pulse <= 0;
  end else begin
    if (!monostable_mode && !astable_mode) begin
      pulse_counter <= 0;
    end
    if (!monostable_mode && trigger) begin
      astable_mode <= 1;
    end
  end
end

endmodule

