module top_module(
    Y,
    A,
    B
);output [3:0] Y;
    input  [3:0] A;
    input  [3:0] B;

    // Voltage supply signals
    supply1 VPWR;
    supply0 VGND;
    supply1 VPB ;
    supply0 VNB ;

    wire [3:0] xnor_out;

    // Use built-in Verilog operator instead of an unknown module
    assign xnor_out[0] = ~(A[0] ^ B[0]);
    assign xnor_out[1] = ~(A[1] ^ B[1]);
    assign xnor_out[2] = ~(A[2] ^ B[2]);
    assign xnor_out[3] = ~(A[3] ^ B[3]);

    assign Y = xnor_out;

endmodule

module top_module(input [31:0] I_dataA,input [31:0] I_dataB,input [2:0] I_branchOp,input I_Cin,output reg O_doBranch);always @* begin 
  case (I_branchOp) 
  0: O_doBranch = (I_dataA == I_dataB); 
  1: O_doBranch = (I_dataA != I_dataB); 
  2: O_doBranch = (I_dataA > I_dataB); 
  3: O_doBranch = (I_dataA >= I_dataB); 
  4: O_doBranch = ($signed(I_dataA) > $signed(I_dataB)); 
  5: O_doBranch = ($signed(I_dataA) >= $signed(I_dataB)); 
  6: O_doBranch = I_Cin; 
  7: O_doBranch = 1; 
  endcase 
 end 
