module washing_machine (
	input clk,
	input resetn,
	output fill,
	output wash,
	output spin);

	parameter FILL=0, WASH=1, SPIN=2;
	reg [1:0] state, next_state;
	reg [3:0] counter;

	always @(posedge clk) begin
		if (~resetn) state <= FILL;
		else state <= next_state;
	end

	always @(posedge clk) begin
		if (state == FILL || state == WASH || state == SPIN) counter <= counter + 1;
		else counter <= 0;
	end

	always_comb begin
		case (state)
			FILL: next_state = (counter == 4'd4) ? WASH : FILL;
			WASH: next_state = (counter == 4'd9) ? SPIN : WASH;
			SPIN: next_state = (counter == 4'd6) ? FILL : SPIN;
			default: next_state = FILL;
		endcase
	end

	assign fill = (state == FILL);
	assign wash = (state == WASH);
	assign spin = (state == SPIN);
endmodule

