module top_module(muxEnable, r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15, out);input [3:0] muxEnable;
input [15:0] r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15;
output reg [15:0] out;

always @(muxEnable, r0, r1, r2, r3, r4, r5, r6, r7, r8, r9, r10, r11, r12, r13, r14, r15)
begin

case (muxEnable)

	4'b0000:
				out = r0;
	4'b0001:
				out = r1;
	4'b0010:
				out = r2;
	4'b0011:
				out = r3;
	4'b0100:
				out = r4;
	4'b0101:
				out = r5;
	4'b0110:
				out = r6;
	4'b0111:
				out = r7;
	4'b1000:
				out = r8;
	4'b1001:
				out = r9;
	4'b1010:
				out = r10;
	4'b1011:
				out = r11;
	4'b1100:
				out = r12;
	4'b1101:
				out = r13;
	4'b1110:
				out = r14;
	4'b1111:
				out = r15;
	default: 
				out = 16'b0000_0000_0000_0000;
	endcase
end


endmodule

module top_module(
  input a,
  input b,
  input c,
  input d,
  output y
);// Voltage supply signals
  supply1 VPWR;
  supply0 VGND;
  supply1 VPB;
  supply0 VNB;

  wire ab;
  wire cd;
  wire abcd;

  // Instantiate a 2-input NOR gate
  assign ab = ~(a | b);
  assign cd = ~(c | d);
  assign abcd = ~(ab | cd);

  // Final output as NOR of abcd
  assign y = ~abcd;

endmodule

